import { createConsentManager, createMemoryStorage } from "@permitojs/core";
const manager = createConsentManager({
  consentVersion: "2026-10",
  storage: createMemoryStorage(),
  categories: [{ id: "necessary", required: true }, { id: "marketing" }],
  purposes: [
    { id: "newsletter", category: "marketing" },
    { id: "retargeting", category: "marketing" },
  ],
});
await manager.ready;
await manager.update({ marketing: true });
console.log("newsletter:", manager.hasPurposeConsent("newsletter"));
console.log("retargeting:", manager.hasPurposeConsent("retargeting"));
await manager.setPurposeConsent("retargeting", false);
console.log("after decline -> retargeting:", manager.hasPurposeConsent("retargeting"));
console.log("purposes:", JSON.stringify(manager.getSnapshot().purposes));

import { createConsentManager, createMemoryStorage, connectConsentWebhook, parseConsentWebhookPayload } from "@permitojs/core";
const manager = createConsentManager({
  consentVersion: "2026-10",
  storage: createMemoryStorage(),
  categories: [{ id: "necessary", required: true }, { id: "marketing" }],
  purposes: [{ id: "newsletter", category: "marketing" }],
});
await manager.ready;
const received = [];
connectConsentWebhook(manager, {
  url: "https://example.com/consent-hook",
  subject: "customer-4711",
  fetch: async (url, init) => { received.push(init.body); return new Response(null, { status: 204 }); },
});
await manager.update({ marketing: true });
await manager.update({ marketing: false });
await new Promise((r) => setTimeout(r, 50));
const payload = parseConsentWebhookPayload(received[1]);
console.log(JSON.stringify(payload, null, 2));

import { createConsentManager } from "@permitojs/core";
const stored1x = { schema: 1, version: "2026-10", timestamp: "2026-09-01T10:00:00.000Z",
  categories: { necessary: true, statistics: true, marketing: false }, services: {}, source: "banner" };
const manager = createConsentManager({
  consentVersion: "2026-10",
  categories: [{ id: "necessary", required: true }, { id: "statistics" }, { id: "marketing" }],
  initialState: stored1x,
});
await manager.ready;
const s = manager.getSnapshot();
console.log("needsConsent:", s.needsConsent);
console.log("decision.schema:", s.decision.schema);
console.log("purposes:", JSON.stringify(s.purposes));
